cssCode:
#container { display: flex; justify-content: center; align-items: center; background: #e0e0e0; }
.morph-btn {
  padding: 15px 40px; font-size: 18px; font-weight: bold; color: white;
  border: none; cursor: pointer; text-transform: uppercase; letter-spacing: 2px;
  background: linear-gradient(90deg, #6c63ff, #00d2ff, #6c63ff); background-size: 200%;
  border-radius: 30px 10px 30px 10px; /* અનિયમિત આકાર */
  box-shadow: 0 10px 20px rgba(108,99,255,0.3);
  animation: blobify 4s ease-in-out infinite, gradientFlow 4s linear infinite;
  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.morph-btn:hover { transform: scale(1.1) translateY(-5px); box-shadow: 0 15px 30px rgba(108,99,255,0.4); }
@keyframes blobify {
  0%, 100% { border-radius: 30px 10px 30px 10px; }
  50% { border-radius: 10px 30px 10px 30px; }
}
@keyframes gradientFlow { 0% { background-position: 0% 50%; } 100% { background-position: 100% 50%; } }

